'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '../..');
const read = file => fs.readFileSync(path.join(root, file), 'utf8');

const bootstrap = read('docs/scifi-ui/scripts/formatx-core-real3d-v20.js');
const desktopRuntime = read('docs/scifi-ui/scripts/formatx-core-reference-v53.js');
const mobileRuntime = read('docs/scifi-ui/scripts/formatx-core-mobile-v55.js');
const sharedRuntime = read('docs/scifi-ui/scripts/formatx-core-reference-cinematic-v1.js');
const mobileStyle = read('docs/scifi-ui/styles/formatx-core-mobile-v55.css');
const homepage = read('docs/scifi-ui/index.html');

assert.match(bootstrap, /reference-crystal-core-v53/);
assert.match(bootstrap, /const MOBILE_SCRIPT = '\/scifi-ui\/scripts\/formatx-core-mobile-v55\.js/);
assert.match(bootstrap, /const MOBILE_STYLE = '\/scifi-ui\/styles\/formatx-core-mobile-v55\.css/);
assert.match(bootstrap, /formatx-core-reference-v53\.js\?v=20260812-four-point-reference-r1/);
assert.match(bootstrap, /formatx-core-reference-v53\.css\?v=20260812-four-point-reference-r1/);
assert.match(bootstrap, /formatx-core-mobile-v55\.js\?v=20260812-four-point-reference-r1/);
assert.match(bootstrap, /formatx-core-mobile-v55\.css\?v=20260812-four-point-reference-r1/);
assert.match(bootstrap, /single-webgl2-reference-crystal-v53/);
assert.match(bootstrap, /single-webgl2-mobile-cinematic-crystal-v55/);
assert.match(bootstrap, /if \(mobile\) \{[\s\S]*addMobileStyle\(\);[\s\S]*addMobileScript\(\);[\s\S]*\} else \{[\s\S]*addStyle\(\);[\s\S]*addScript\(\);/);

assert.match(desktopRuntime, /fxCoreRendererMode = 'desktop'/);
assert.match(mobileRuntime, /fxCoreRendererMode = 'mobile'/);
assert.match(desktopRuntime, /formatx-core-reference-cinematic-v1\.js\?v=20260812-four-point-reference-r1/);
assert.match(mobileRuntime, /formatx-core-reference-cinematic-v1\.js\?v=20260812-four-point-reference-r1/);
assert.equal((desktopRuntime.match(/getContext\(['"]webgl2['"]/g) || []).length, 0);
assert.equal((mobileRuntime.match(/getContext\(['"]webgl2['"]/g) || []).length, 0);
assert.equal((sharedRuntime.match(/getContext\(['"]webgl2['"]/g) || []).length, 1, 'one shared WebGL2 context creation site required');

assert.match(sharedRuntime, /hero && hero\.querySelector\('\.hero-space'\)/);
assert.match(sharedRuntime, /if\(mobile\) host\.prepend\(stage\)/);
assert.match(sharedRuntime, /premultipliedAlpha:true/);
assert.match(sharedRuntime, /budget=mobile\?1100000:2500000/);
assert.match(sharedRuntime, /powerPreference:mobile\?'default':'high-performance'/);
assert.match(sharedRuntime, /ResizeObserver/);
assert.match(sharedRuntime, /IntersectionObserver/);
assert.match(sharedRuntime, /webglcontextlost/);
assert.match(sharedRuntime, /long-sharp-four-tip-deep-concave-crystal-v55/);
assert.match(sharedRuntime, /thin-layered-faceted-fresnel-glass-v55/);
assert.match(sharedRuntime, /small-hot-white-nucleus-concentric-cyan-violet-rings-v55/);
assert.match(sharedRuntime, /single-context-adaptive-60-plus-fps/);
assert.match(sharedRuntime, /physical-triangle-ribbons-interactive-r2/);
assert.match(sharedRuntime, /inside-moving-volume-r2/);
assert.match(sharedRuntime, /function outlineRadius\(/);
assert.match(sharedRuntime, /function buildShell\(/);
assert.match(sharedRuntime, /direct-pointer-touch-drag-r4-living-system/);
assert.match(sharedRuntime, /webgl2-unavailable-v55/);
assert.match(sharedRuntime, /context-unavailable-v55/);
assert.doesNotMatch(sharedRuntime, /new\s+Image\s*\(|drawImage\s*\(|createImageBitmap\s*\(/i);

assert.match(mobileStyle, /#hero \.hero-space > \.fx-core-mobile-v55-stage/);
assert.match(mobileStyle, /position:\s*absolute\s*!important/);
assert.match(mobileStyle, /filter:\s*none\s*!important/);
assert.match(mobileStyle, /contain:\s*none\s*!important/);
assert.match(mobileStyle, /height:\s*clamp\(590px,68svh,760px\)/);
assert.doesNotMatch(mobileStyle, /clip-path:\s*polygon/i);
assert.ok(homepage.includes('formatx-core-real3d-v20.js'));
new Function(desktopRuntime);new Function(mobileRuntime);new Function(sharedRuntime);new Function(bootstrap);
console.log('PASS: desktop v53 and mobile v55 use one shared native WebGL2 four-point crystal renderer; mobile stays hero-local, premultiplied, adaptive, interactive and fail-open.');
